package com.findit.controller;
import com.findit.model.*; import com.findit.repository.*; import com.findit.service.*; import org.springframework.http.MediaType; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.io.IOException; import java.time.LocalDate; import java.util.*; import java.util.stream.Collectors;
@Controller
public class WebController {
 final UserRepository users; final ItemRepository items; final MatchRepository matches; final ClaimRepository claims; final NotificationRepository notices; final UserService userService; final StorageService storage; final MatchingService matching;
 final List<String> categories=List.of("Electronics","Bags","Wallets","Watches","Keys","Books","Documents","ID Cards","Clothing","Accessories","Other");
 final List<String> colors=List.of("Black","White","Blue","Red","Green","Yellow","Brown","Grey","Other");
 WebController(UserRepository u,ItemRepository i,MatchRepository m,ClaimRepository c,NotificationRepository n,UserService us,StorageService s,MatchingService ms){users=u;items=i;matches=m;claims=c;notices=n;userService=us;storage=s;matching=ms;}
 AppUser me(Authentication a){if(a==null||!a.isAuthenticated()||a.getName().equals("anonymousUser"))return null;return users.findByEmailIgnoreCase(a.getName()).orElse(null);}
 void common(Model m){m.addAttribute("categories",categories);m.addAttribute("colors",colors);}
 @GetMapping("/") String home(Model m){m.addAttribute("recent",items.findTop8ByStatusOrderByCreatedAtDesc(ItemStatus.ACTIVE));return "index";}
 @GetMapping("/register") String regForm(Model m){m.addAttribute("formUser",new AppUser());return "register";}
 @PostMapping("/register") String reg(@ModelAttribute("formUser") AppUser u,@RequestParam String password,@RequestParam String confirmPassword,Model m,RedirectAttributes ra){try{if(!password.equals(confirmPassword))throw new IllegalArgumentException("Passwords do not match.");if(password.length()<8)throw new IllegalArgumentException("Password must be at least 8 characters.");userService.register(u,password);ra.addFlashAttribute("success","Account created. Please log in.");return "redirect:/login";}catch(IllegalArgumentException e){m.addAttribute("error",e.getMessage());return "register";}}
 @GetMapping("/login") String login(){return "login";}
 @GetMapping("/dashboard") String dashboard(Authentication a,Model m){AppUser u=me(a);m.addAttribute("user",u);m.addAttribute("lostCount",items.countByOwnerIdAndItemType(u.getId(),ItemType.LOST));m.addAttribute("foundCount",items.countByOwnerIdAndItemType(u.getId(),ItemType.FOUND));m.addAttribute("claimCount",claims.countByClaimantId(u.getId()));m.addAttribute("myItems",items.findByOwnerIdOrderByCreatedAtDesc(u.getId()));m.addAttribute("myNotifications",notices.findTop8ByUserIdOrderByCreatedAtDesc(u.getId()));return "dashboard";}
 @GetMapping("/report/{type}") String reportForm(@PathVariable String type,Model m){if(!type.equalsIgnoreCase("lost")&&!type.equalsIgnoreCase("found"))return "redirect:/";common(m);m.addAttribute("type",type.toUpperCase());return "report";}
 @PostMapping(value="/report/{type}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) String report(@PathVariable String type,@RequestParam String itemName,@RequestParam String category,@RequestParam(required=false) String color,@RequestParam String location,@RequestParam(required=false) String description,@RequestParam(required=false) String itemDate,@RequestParam(required=false) MultipartFile image,Authentication a,Model model,RedirectAttributes ra){
  if(!type.equalsIgnoreCase("lost")&&!type.equalsIgnoreCase("found"))return "redirect:/";AppUser u=me(a);
  try{Item it=new Item();it.setOwner(u);it.setItemType(ItemType.valueOf(type.toUpperCase()));it.setItemName(itemName.trim());it.setCategory(category);it.setColor(color);it.setLocation(location.trim());it.setDescription(description);it.setItemDate(itemDate==null||itemDate.isBlank()?null:LocalDate.parse(itemDate));it.setImagePath(storage.store(image));items.save(it);
   if(it.getItemType()==ItemType.LOST){List<MatchRecord> mm=matching.findMatches(it);ra.addFlashAttribute("success",mm.isEmpty()?"Report saved. We'll keep checking for possible matches.":"Report saved. Possible matches are ready to view.");}else{matching.compareFound(it);ra.addFlashAttribute("success","Found item report saved.");}return "redirect:/dashboard";
  }catch(IOException|IllegalArgumentException e){common(model);model.addAttribute("type",type.toUpperCase());model.addAttribute("error",e.getMessage());return "report";}}
 @GetMapping("/gallery") String gallery(@RequestParam(required=false) String q,@RequestParam(required=false) String status,@RequestParam(required=false) String category,@RequestParam(required=false) String location,Model m){
  List<Item> all=new ArrayList<>(items.findByItemTypeAndStatus(ItemType.LOST,ItemStatus.ACTIVE));all.addAll(items.findByItemTypeAndStatus(ItemType.FOUND,ItemStatus.ACTIVE));String qq=val(q).toLowerCase(),ss=val(status).toUpperCase(),cc=val(category),ll=val(location).toLowerCase();
  List<Item> out=all.stream().filter(i->(qq.isBlank()||(val(i.getItemName())+" "+val(i.getDescription())+" "+val(i.getColor())).toLowerCase().contains(qq))&&(ss.isBlank()||i.getItemType().name().equals(ss))&&(cc.isBlank()||i.getCategory().equals(cc))&&(ll.isBlank()||i.getLocation().toLowerCase().contains(ll))).sorted(Comparator.comparing(Item::getCreatedAt).reversed()).collect(Collectors.toList());
  common(m);m.addAttribute("items",out);m.addAttribute("q",val(q));m.addAttribute("status",val(status));m.addAttribute("category",val(category));m.addAttribute("location",val(location));return "gallery";}
 String val(String s){return s==null?"":s;}
 @GetMapping("/item/{id}") String detail(@PathVariable Long id,Model m){Item i=items.findById(id).orElse(null);if(i==null)return "redirect:/gallery";m.addAttribute("item",i);return "item";}
 @GetMapping("/matches/{id}") String matchPage(@PathVariable Long id,Authentication a,Model m){AppUser u=me(a);Item it=items.findById(id).orElse(null);if(it==null||!it.getOwner().getId().equals(u.getId())||it.getItemType()!=ItemType.LOST)return "redirect:/dashboard";m.addAttribute("item",it);m.addAttribute("matches",matching.findMatches(it));return "matches";}
 @GetMapping("/claim/{id}") String claimForm(@PathVariable Long id,Model m){Item it=items.findById(id).orElse(null);if(it==null||it.getItemType()!=ItemType.FOUND)return "redirect:/gallery";m.addAttribute("item",it);return "claim";}
 @PostMapping("/claim/{id}") String claim(@PathVariable Long id,@RequestParam String proof,Authentication a,RedirectAttributes ra){AppUser u=me(a);Item it=items.findById(id).orElse(null);if(it==null||it.getItemType()!=ItemType.FOUND||proof.isBlank()){ra.addFlashAttribute("error","Unable to submit claim.");return "redirect:/gallery";}Claim c=new Claim();c.setItem(it);c.setClaimant(u);c.setProof(proof.trim());claims.save(c);Notification n=new Notification();n.setUser(it.getOwner());n.setMessage("A claim was submitted for '"+it.getItemName()+"'.");notices.save(n);ra.addFlashAttribute("success","Claim submitted for verification.");return "redirect:/dashboard";}
 @GetMapping("/notifications") String notificationPage(Authentication a,Model m){m.addAttribute("allNotifications",notices.findByUserIdOrderByCreatedAtDesc(me(a).getId()));return "notifications";}
 @GetMapping("/admin") String admin(Model m){m.addAttribute("userCount",users.count());m.addAttribute("lostCount",items.countByItemType(ItemType.LOST));m.addAttribute("foundCount",items.countByItemType(ItemType.FOUND));m.addAttribute("pendingClaims",claims.countByStatus(ClaimStatus.PENDING));m.addAttribute("strongMatches",matches.countByScoreGreaterThanEqual(60));m.addAttribute("activity",items.findAll().stream().sorted(Comparator.comparing(Item::getCreatedAt).reversed()).limit(10).toList());return "admin";}
 @GetMapping("/admin/claims") String adminClaims(Model m){m.addAttribute("claims",claims.findAllByOrderByCreatedAtDesc());return "admin-claims";}
 @PostMapping("/admin/claims/{id}/{action}") String claimAction(@PathVariable Long id,@PathVariable String action,RedirectAttributes ra){Claim c=claims.findById(id).orElse(null);if(c==null||(!action.equals("approve")&&!action.equals("reject")))return "redirect:/admin/claims";c.setStatus(action.equals("approve")?ClaimStatus.APPROVED:ClaimStatus.REJECTED);if(action.equals("approve"))c.getItem().setStatus(ItemStatus.RETURNED);claims.save(c);Notification n=new Notification();n.setUser(c.getClaimant());n.setMessage("Your claim for '"+c.getItem().getItemName()+"' was "+action+"d.");notices.save(n);ra.addFlashAttribute("success","Claim updated.");return "redirect:/admin/claims";}
 @GetMapping(value="/api/items",produces=MediaType.APPLICATION_JSON_VALUE) @ResponseBody List<Map<String,Object>> api(){List<Item> all=new ArrayList<>(items.findByItemTypeAndStatus(ItemType.LOST,ItemStatus.ACTIVE));all.addAll(items.findByItemTypeAndStatus(ItemType.FOUND,ItemStatus.ACTIVE));return all.stream().map(i->{Map<String,Object> x=new LinkedHashMap<>();x.put("id",i.getId());x.put("type",i.getItemType());x.put("name",i.getItemName());x.put("category",i.getCategory());x.put("color",i.getColor());x.put("location",i.getLocation());x.put("imagePath",i.getImagePath());x.put("status",i.getStatus());return x;}).toList();}
}
